    ('cron_job', 'cron', 'aidwar-billing-notify', NULL, NULL, 'schedule */5 * * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-billing-sweep', NULL, NULL, 'schedule */30 * * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-campaign-worker', NULL, NULL, 'schedule * * * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-flow-scan', NULL, NULL, 'schedule 0 4 * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-flow-worker', NULL, NULL, 'schedule * * * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-knowledge-backfill', NULL, NULL, 'schedule 0 21 * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-knowledge-refresh', NULL, NULL, 'schedule 20 */6 * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-knowledge-worker', NULL, NULL, 'schedule * * * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-plan-billing', NULL, NULL, 'schedule 30 3 * * *', '20260923_plan_billing_cron.sql'),
    ('cron_job', 'cron', 'aidwar-reprice-sweep', NULL, NULL, 'schedule */10 * * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-reprocess-events', NULL, NULL, 'schedule */5 * * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-retention-purge', NULL, NULL, 'schedule 0 2 * * *', '20261053_cron_jobs.sql'),
    ('cron_job', 'cron', 'aidwar-shopify-sync', NULL, NULL, 'schedule * * * * *', '20261053_cron_jobs.sql')
),
cron_jobs AS (
  SELECT (xpath('/row/jobname/text()', r))[1]::text AS jobname
  FROM unnest(xpath('/table/row',
    CASE WHEN to_regclass('cron.job') IS NOT NULL
      THEN query_to_xml('SELECT jobname FROM cron.job', true, false, '')
    END)) AS r
),
expected_fn AS (
  SELECT e.*,
    (SELECT coalesce(array_agg(to_regtype(t)::oid ORDER BY i), '{}'::oid[])
       FROM unnest(e.arg_types) WITH ORDINALITY AS u(t, i)) AS arg_oids
  FROM expected e
  WHERE e.kind = 'function'
),
missing AS (
  SELECT f.kind,
    f.schema_name || '.' || f.object_name || '(' || array_to_string(f.arg_types, ', ') || ')' AS name,
    coalesce('found only: ' || (
      SELECT string_agg(f.object_name || '(' || pg_get_function_identity_arguments(p.oid) || ')', '; ')
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = f.schema_name AND p.proname = f.object_name
    ), 'no function of this name') AS detail,
    f.introduced_in_file
  FROM expected_fn f
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = f.schema_name AND p.proname = f.object_name
      AND p.proargtypes::oid[] = f.arg_oids
  )
  UNION ALL
  SELECT e.kind, e.schema_name || '.' || e.object_name, e.detail, e.introduced_in_file
  FROM expected e
  WHERE e.kind IN ('table', 'view', 'index')
    AND NOT EXISTS (
      SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = e.schema_name AND c.relname = e.object_name
        AND c.relkind = ANY (CASE e.kind
          WHEN 'table' THEN ARRAY['r', 'p']::"char"[]
          WHEN 'view' THEN ARRAY['v', 'm']::"char"[]
          ELSE ARRAY['i', 'I']::"char"[] END)
    )
  UNION ALL
  SELECT e.kind, e.schema_name || '.' || e.object_name || '.' || e.sub_name, e.detail, e.introduced_in_file
  FROM expected e
  WHERE e.kind = 'column'
    AND NOT EXISTS (
      SELECT 1 FROM pg_attribute a
      JOIN pg_class c ON c.oid = a.attrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = e.schema_name AND c.relname = e.object_name
        AND a.attname = e.sub_name AND a.attnum > 0 AND NOT a.attisdropped
    )
  UNION ALL
  SELECT e.kind, e.sub_name, e.detail, e.introduced_in_file
  FROM expected e
  WHERE e.kind = 'trigger'
    AND NOT EXISTS (
      SELECT 1 FROM pg_trigger t
      JOIN pg_class c ON c.oid = t.tgrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = e.schema_name AND c.relname = e.object_name
        AND t.tgname = e.sub_name AND NOT t.tgisinternal
    )
  UNION ALL
  SELECT e.kind, e.object_name,
    CASE WHEN to_regclass('cron.job') IS NULL THEN 'pg_cron not installed (cron.job missing)'
      ELSE e.detail END,
    e.introduced_in_file
  FROM expected e
  WHERE e.kind = 'cron_job'
    AND NOT EXISTS (SELECT 1 FROM cron_jobs j WHERE j.jobname = e.object_name)
)
SELECT kind, name, detail, introduced_in_file
FROM missing
ORDER BY array_position(ARRAY['table', 'column', 'view', 'function', 'index', 'trigger', 'cron_job'], kind), introduced_in_file, name;
